-- MIGRASI CASH FEBRUARI 2026 - LANGSUNG BERISI DATA
-- Target: PostgreSQL Prisma schema final Clicco Finance
-- CashTransaction: 976 rows
-- DebtMutation opening piutang: 9 rows
-- Total INCOME: 1183690348
-- Total EXPENSE: 820064016
-- NET CASH: 363626332
-- Total PIUTANG AWAL: 139190933

BEGIN;


-- Bersihkan data migrasi yang sama supaya aman dijalankan ulang
DELETE FROM "DebtMutation" WHERE description LIKE '[MIGRASI CASH FEB 2026]%';
DELETE FROM "CashTransaction" WHERE description LIKE '[MIGRASI CASH FEB 2026]%';

-- VALIDASI MASTER DATA WAJIB ADA
-- Rekening yang dipakai: BCA, BRI, BRI CV, CASH, CASH / TUNAI, DANA, JENIUS, MANDIRI, MANDIRI CV, OVO, SHOPEE
-- Kategori yang dipakai: BEBAN BONUS KARYAWAN, BEBAN GAPOK, BEBAN LAIN, HPP, IKLAN, MODAL AWAL, PENARIKAN MODAL, PENDAPATAN CUST TF, PENDAPATAN LAIN, PENDAPATAN LAZADA, PENDAPATAN PENCAIRAN BAC, PENDAPATAN PENCAIRAN EVERPRO, PENDAPATAN SHOPEE, PENDAPATAN TIK TOK SHOP
-- Subkategori yang dipakai: ASURANSI DAN BPJS, BIAYA ADMIN, BIAYA AIR, BIAYA KOMUNIKASI, BIAYA LAINYA, BIAYA LISTRIK, BIAYA OPR KANTOR, BIAYA PACKING, BIAYA WIFI, BONUS BOLA TERAPI, BONUS EARPLUG, ITEM BONUS ALAT PIJAT, KEGIATAN SABTU, LANGGANAN SOFTWARE, MATERAI, MEETING/INTERTIMENT, ONGKIR PAKET, PAJAK, REFUND DANA, THR, ZAKAT

-- INSERT CASH TRANSACTION

-- INSERT / UPSERT DEBT ENTITY + DEBT MUTATION UNTUK SALDO AWAL PIUTANG
-- CSV_ROW 5 - MAS ALI FIRYADIANSYAH
WITH existing_entity AS (
  SELECT id FROM "DebtEntity" WHERE UPPER(name) = UPPER('MAS ALI FIRYADIANSYAH') AND type = 'PIUTANG'::"DebtType" LIMIT 1
), inserted_entity AS (
  SELECT gen_random_uuid()::text, 'MAS ALI FIRYADIANSYAH', 'PIUTANG'::"DebtType", false, NOW(), NOW()
  WHERE NOT EXISTS (SELECT 1 FROM existing_entity)
  RETURNING id
), entity_row AS (
  SELECT id FROM existing_entity UNION ALL SELECT id FROM inserted_entity LIMIT 1
)
SELECT gen_random_uuid()::text, id, '2026-02-01T00:00:00.000+07:00', 4000000, 'ADD_DEBT'::"DebtMutationType", '[MIGRASI CASH FEB 2026][CSV_ROW:5] Saldo awal piutang - Mas ALI Firyadiansyah', NULL, NOW(), NOW() FROM entity_row;
