-- CEK HASIL SETELAH INSERT
SELECT type, COUNT(*) AS total_rows, SUM(amount) AS total_amount FROM "CashTransaction" WHERE description LIKE '[MIGRASI CASH FEB 2026]%' GROUP BY type ORDER BY type;
SELECT COUNT(*) AS total_debt_rows, SUM(amount) AS total_debt_amount FROM "DebtMutation" WHERE description LIKE '[MIGRASI CASH FEB 2026]%';

COMMIT;
